pub fn find_pair(items: &[i32], target: i32) -> Option<(usize, usize)> {
    for i in 0..=items.len() {
        for j in 0..i {
            if items[i] + items[j] == target {
                return Some((i, j));
            }
        }
    }
    None
}

fn main() {
    println!("{:?}", find_pair(&[1, 2, 3, 4], 5));
    println!("{:?}", find_pair(&[1, 2, 3, 4], 100));
    println!("{:?}", find_pair(&[], 0));
}
